-- PROPOSITION de migration R4 : contraintes composites (id, organizationId). NE PAS COPIER DANS prisma/migrations
-- avant revue : Railway exécute `prisma migrate deploy` à chaque déploiement.
-- Prérequis : detect-cross-org.sql renvoie 0 partout sur la base visée (voir README.md).
--
-- Principe : chaque parent expose UNIQUE (id, "organizationId"). Chaque enfant remplace sa clé étrangère simple
-- par une clé composite (colonne, "organizationId") : PostgreSQL refuse alors toute référence vers une ligne d'un autre institut,
-- y compris pour un rôle qui ignore RLS. Les actions ON DELETE / ON UPDATE d'origine sont conservées.
-- Ordre sans coupure : 1) UNIQUE concurrent, 2) FK composite NOT VALID, 3) VALIDATE (verrou léger), 4) suppression de l'ancienne FK.
-- Les colonnes nullables (ON DELETE SET NULL) utilisent la forme PostgreSQL 15+ : SET NULL (colonne), sans toucher à organizationId.
-- Les index CREATE UNIQUE INDEX CONCURRENTLY ne peuvent pas tourner dans une transaction : exécuter la partie A hors `prisma migrate`.

-- ===== PARTIE A : index uniques (hors transaction) =====
CREATE UNIQUE INDEX CONCURRENTLY IF NOT EXISTS "Appointment_id_organizationId_key" ON "Appointment" (id, "organizationId");
CREATE UNIQUE INDEX CONCURRENTLY IF NOT EXISTS "AssistantConversation_id_organizationId_key" ON "AssistantConversation" (id, "organizationId");
