CREATE UNIQUE INDEX CONCURRENTLY IF NOT EXISTS "GiftCard_id_organizationId_key" ON "GiftCard" (id, "organizationId");
CREATE UNIQUE INDEX CONCURRENTLY IF NOT EXISTS "Invoice_id_organizationId_key" ON "Invoice" (id, "organizationId");
CREATE UNIQUE INDEX CONCURRENTLY IF NOT EXISTS "LoyaltyAccount_id_organizationId_key" ON "LoyaltyAccount" (id, "organizationId");
